const I=n=>`ph/${n}.jpg`;
const g=(id)=>id?` data-go="${id}"`:'';
const NAV=(title,{back='',right='',close=false}={})=>`<div class="nav"><div class="gh"${g(back)}>${back||close?ic(close?'x':'chevL','style="width:26px;height:26px"'):''}</div>${title?`<div class="t">${title}</div>`:''}<div>${right}</div></div>`;
const FIELD=(label,val,{ph=false,st='',icon='',right='',hint='',hst='',area=false}={})=>`<div class="fl">${label?`<label>${label}</label>`:''}<div class="inp ${st} ${area?'area':''}">${icon?ic(icon):''}<span class="sp ${ph?'ph-t':''}">${val}${st==='focus'?'<span class="caret"></span>':''}</span>${right}</div>${hint?`<div class="hint ${hst}">${hst==='err'?ic('alert'):hst==='ok'?ic('check'):''}${hint}</div>`:''}</div>`;
const PROG=(n,t=3,back='',skip='')=>`<div class="nav"><div class="gh"${g(back)}>${back?ic('chevL','style="width:26px;height:26px"'):''}</div><div class="prog">${Array.from({length:t},(_,i)=>`<i class="${i<n?'on':''}"></i>`).join('')}</div><span class="stepl">${n} из ${t}</span>${skip?`<span class="lnk" style="margin-left:6px"${g(skip)}>Пропустить</span>`:''}</div>`;
const LI=(icon,t,v='',{go='',danger=false,tg=null,chev=true}={})=>`<div class="li ${icon?'':'noi'} ${danger?'danger':''}"${g(go)}>${icon?`<div class="lico" style="${danger?'color:var(--pink)':''}">${ic(icon)}</div>`:''}<span>${t}</span>${tg!==null?`<div class="tg ${tg?'on':''}"></div>`:`<span class="v">${v}${chev?ic('chevR'):''}</span>`}</div>`;
const UTAB=(on,map=['homeP','swipes','mapNow','compSearch','prof'])=>{const t=[['home','Афиша'],['cards','Свайпы'],['map','Карта'],['users','Компания'],['user','Профиль']];
return `<div class="tabbar">${t.map(([i,l],k)=>`<div class="tab ${k===on?'on':''}"${g(map[k])}>${ic(i)}<span>${l}</span></div>`).join('')}</div><div class="homeind"></div>`};
const BTAB=(on)=>{const t=[['grid','Обзор','d1'],['calendar','События','d2'],['chart','Аудитория','d4'],['chat','Сообщения','d5'],['gear','Настройки','d6']];
return `<div class="tabbar biztab">${t.map(([i,l,go],k)=>`<div class="tab ${k===on?'on':''}"${g(go)} style="position:relative">${ic(i)}<span>${l}</span>${k===3?'<i class="dot" style="position:absolute;top:8px;right:18px;width:7px;height:7px"></i>':''}</div>`).join('')}</div><div class="homeind"></div>`};
const SCR=(id,inner,cls='')=>`<div class="screen ${cls}" id="${id}">${STATUS}${inner}</div>`;
const HI='<div class="homeind"></div>';
const AV=(n,s=32,ring='')=>`<img class="av" style="width:${s}px;height:${s}px;${ring}" src="${I(n)}">`;
const BIZHEAD=(sub='Бар · Немига')=>`<div style="display:flex;align-items:center;gap:12px"><div class="logo-v" style="background:var(--pink);color:#fff">13</div><div style="flex:1;min-width:0"><div style="display:flex;align-items:center;gap:6px"><span class="t-h3" style="font-size:18px">Loft 13</span>${ic('chevD','style="width:18px;height:18px;color:var(--text2)"')}</div><div style="display:flex;gap:8px;align-items:center;margin-top:3px"><span class="status st-ok" style="height:20px;font-size:11px"><i></i>Подтверждено</span><span class="t-cap" style="font-size:12px">${sub}</span></div></div></div>`;
window.SCREENS=[];
const add=(id,group,title,logic,html,extra={})=>SCREENS.push({id,group,title,logic,html,...extra});
